"use client";

import { useEffect, useRef, type HTMLAttributes } from "react";

export function MessageScroller({ follow = true, className = "", children, ...props }: HTMLAttributes<HTMLDivElement> & { follow?: boolean }) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { if (follow && ref.current) ref.current.scrollTop = ref.current.scrollHeight; }, [children, follow]); return <div ref={ref} role="log" aria-live="polite" aria-relevant="additions" tabIndex={0} className={`co-max-h-96 co-overflow-y-auto co-rounded-lg focus-visible:co-ring-2 ${className}`.trim()} {...props}>{children}</div>; }
